28	    @Mapping(target = "identityKey", expression = "java(formatIdentityKey(owner))")
29	    @Mapping(target = "bulkSignupWarning", ignore = true)
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /**
33	     * Derives an owner's duplicate-detection identity key as
34	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'} from the stored
35	     * (already E.164-normalized) telephone, lower-cased email and household id. A {@code null}
36	     * telephone, email or household id contributes the empty string in its position.
37	     */
38	    default String formatIdentityKey(Owner owner) {
39	        if (owner == null) {
40	            return null;
41	        }
42	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
43	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
44	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
45	        return telephone + "|" + email + "|" + householdId;
46	    }
47	
48	    /**
49	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
50	     * (non-null and non-blank), otherwise {@code PHONE}.
51	     */
52	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
53	        if (owner == null) {
54	            return null;
55	        }
56	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
57	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
58	    }
59	
60	    /**
61	     * Derives an owner's locality (region) preferring the postcode: the region is resolved by
62	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only when the
63	     * postcode is absent or in no known range does it fall back to the fixed city-to-region table
64	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns
65	     * {@code "UNKNOWN"} when neither the postcode nor the city resolves to a region.
66	     */
67	    default String formatLocality(Owner owner) {
68	        if (owner == null) {
69	            return null;
70	        }
71	        String fromPostcode = regionForPostcode(owner.getPostcode());
72	        if (fromPostcode != null) {
73	            return fromPostcode;
74	        }
75	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
76	            case "Sydney" -> "NSW";
77	            case "Melbourne" -> "VIC";
78	            case "Brisbane" -> "QLD";
79	            default -> "UNKNOWN";
80	        };
81	    }
82	
83	    /**
84	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
85	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
86	     * no known range, signalling that the caller should fall back to the city-to-region table.
87	     */
88	    private String regionForPostcode(String postcode) {
89	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
90	            return null;
91	        }
92	        int value = Integer.parseInt(postcode);
93	        if (value >= 2000 && value <= 2099) {
94	            return "NSW";
95	        }
96	        if (value >= 3000 && value <= 3099) {
97	            return "VIC";
98	        }
99	        if (value >= 4000 && value <= 4099) {
100	            return "QLD";
101	        }
102	        return null;
103	    }
104	
105	    /**
106	     * Computes an owner's membership level, a number from 1 to 3: starting at 1, plus 1 when an email
107	     * is present, plus 1 when the owner's namesake count is 0, capped at 3 (level 4 is reserved for
108	     * tenure).
109	     */
110	    default Integer formatMembershipLevel(Owner owner) {
111	        if (owner == null) {
112	            return null;
113	        }
114	        int level = 1;
115	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
116	        if (hasEmail) {
117	            level++;
118	        }
119	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
120	        if (unique) {
121	            level++;
122	        }
123	        return Math.min(level, 3);
124	    }
125	
126	    /**
127	     * Computes an owner's check digit: a single Luhn check digit (0-9) over the digits contained in the
128	     * customer code. Returns {@code null} when the customer code is absent.
129	     */
130	    default Integer formatCheckDigit(Owner owner) {
131	        if (owner == null || owner.getCustomerCode() == null) {
132	            return null;
133	        }
134	        String code = owner.getCustomerCode();
135	        int sum = 0;
136	        boolean dbl = true;
137	        for (int i = code.length() - 1; i >= 0; i--) {
138	            char c = code.charAt(i);
139	            if (c < '0' || c > '9') {
140	                continue;
141	            }
142	            int d = c - '0';
143	            if (dbl) {
144	                d *= 2;
145	                if (d > 9) {
146	                    d -= 9;
147	                }
148	            }
149	            sum += d;
150	            dbl = !dbl;
151	        }
152	        return (10 - (sum % 10)) % 10;
153	    }
154	
155	    /**
156	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
157	     * digits of the registration-date year (e.g. {@code "LON-SMI-0007-M26"}). Returns {@code null} when the
158	     * customer code or registration date is absent.
159	     */
160	    default String formatMembershipNumber(Owner owner) {
161	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
162	            return null;
163	        }
164	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
165	    }
166	
167	    /**
168	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
169	     */
170	    default String formatDisplayName(Owner owner) {
171	        if (owner == null) {
172	            return null;
173	        }
174	        return owner.getLastName() + ", " + owner.getFirstName();
175	    }
176	
177	    /**
178	     * Formats an owner's initials as the upper-cased first letters of the first and last
179	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
180	     */
181	    default String formatInitials(Owner owner) {
182	        if (owner == null) {
183	            return null;
184	        }
185	        return initial(owner.getFirstName()) + initial(owner.getLastName());
186	    }
187	
188	    private String initial(String name) {
189	        if (name == null || name.isEmpty()) {
190	            return "";
191	        }
192	        return Character.toUpperCase(name.charAt(0)) + ".";
193	    }
194	
195	    Owner toOwner(OwnerDto ownerDto);
196	
197	    @Mapping(target = "id", ignore = true)
198	    @Mapping(target = "pets", ignore = true)
199	    Owner toOwner(OwnerFieldsDto ownerDto);
200	
201	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
202	
203	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
204	
205	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
206	        OwnerPageDto ownerPageDto = new OwnerPageDto();
207	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
208	        ownerPageDto.setPage(ownerPage.getNumber());
209	        ownerPageDto.setSize(ownerPage.getSize());
210	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
211	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
212	        return ownerPageDto;
213	    }
214	}
