57	
58	@RestController
59	@CrossOrigin(exposedHeaders = "errors, content-type")
60	@RequestMapping("/api")
61	public class OwnerRestControllerV1 implements OwnersApi {
62	
63	    /**
64	     * Syntactic email validation: a non-empty local part, a single '@', and a
65	     * domain with at least one dot-separated label ending in a letter-only TLD.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
69	
70	    /** Dedicated audit logger for owner lifecycle side-effects. */
71	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
72	
73	    private final ClinicService clinicService;
74	
75	    private final OwnerMapper ownerMapper;
76	
77	    private final PetMapper petMapper;
78	
79	    private final VisitMapper visitMapper;
80	
81	    public OwnerRestControllerV1(ClinicService clinicService,
82	                                 OwnerMapper ownerMapper,
83	                                 PetMapper petMapper,
84	                                 VisitMapper visitMapper) {
85	        this.clinicService = clinicService;
86	        this.ownerMapper = ownerMapper;
87	        this.petMapper = petMapper;
88	        this.visitMapper = visitMapper;
89	    }
90	
91	    /**
92	     * Normalise a raw telephone number to E.164 form.
93	     *
94	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
95	     * code are kept when present; otherwise country code '+61' is assumed and a
96	     * single leading '0' is dropped from the national digits. The result must have
97	     * between 8 and 15 digits after the '+'.
98	     *
99	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
100	     * national-number length is additionally validated against that country code:
101	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
102	     * length is wrong for its country is rejected.
103	     *
104	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
105	     */
106	    static String toE164(String raw) {
107	        if (raw == null) {
108	            return null;
109	        }
110	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
111	        String digits;
112	        boolean explicitCountryCode;
113	        if (cleaned.startsWith("+")) {
114	            digits = cleaned.substring(1);
115	            explicitCountryCode = true;
116	        } else {
117	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
118	            digits = "61" + national;
119	            explicitCountryCode = false;
120	        }
121	        if (!digits.matches("[0-9]{8,15}")) {
122	            return null;
123	        }
124	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
125	            return null;
126	        }
127	        return "+" + digits;
128	    }
129	
130	    /**
131	     * Validate the national-number length of an E.164 number (its digits without the
132	     * leading '+') against the requirement for its country code: country code '+61'
133	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
134	     * without a configured length requirement are accepted unchanged.
135	     */
136	    private static boolean hasValidNationalLength(String digits) {
137	        if (digits.startsWith("61")) {
138	            return digits.length() - "61".length() == 9;
139	        }
140	        if (digits.startsWith("1")) {
141	            return digits.length() - "1".length() == 10;
142	        }
143	        return true;
144	    }
145	
146	    /**
147	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
148	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
149	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
150	     * input normalises to the empty string.
151	     */
152	    private static String normaliseIdentity(String value) {
153	        if (value == null) {
154	            return "";
155	        }
156	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
157	    }
158	
159	    /**
160	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
161	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
162	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
163	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
164	     * that is both stored and used for every address comparison.
165	     */
166	    static String normaliseAddress(String value) {
167	        if (value == null) {
168	            return "";
169	        }
170	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
171	        if (collapsed.isEmpty()) {
172	            return "";
173	        }
174	        String[] tokens = collapsed.split(" ");
175	        StringBuilder result = new StringBuilder();
176	        for (int i = 0; i < tokens.length; i++) {
177	            if (i > 0) {
178	                result.append(' ');
179	            }
180	            result.append(expandAddressAbbreviation(tokens[i]));
181	        }
182	        return result.toString();
183	    }
184	
185	    /**
186	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
187	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
188	     * returned unchanged.
189	     */
190	    private static String expandAddressAbbreviation(String token) {
191	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
192	        return switch (core) {
193	            case "ST" -> "STREET";
194	            case "RD" -> "ROAD";
195	            case "AVE" -> "AVENUE";
196	            default -> token;
197	        };
198	    }
199	
200	    /**
201	     * Derive the stable, shared household identifier for owners sharing a household. It is a
202	     * deterministic UUID over the normalised last-name and address, so every owner in the same
203	     * household resolves to the same value regardless of the order in which they were created.
204	     */
205	    private static String householdId(String lastNameKey, String addressKey) {
206	        String seed = lastNameKey + "�" + addressKey;
207	        return UUID.nameUUIDFromBytes(seed.getBytes(StandardCharsets.UTF_8)).toString();
208	    }
209	
210	    /**
211	     * Build an owner's derived duplicate-detection identity key as
212	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
213	     * component contributes the empty string, and the email is lower-cased so the comparison is
214	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
215	     */
216	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
217	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
218	        String emailKey = email == null ? "" : email.toLowerCase();
219	        String household = householdId == null ? "" : householdId;
220	        return telephone + "|" + emailKey + "|" + household;
221	    }
222	
223	    /**
224	     * Build the customer code for a new owner as {@code '<CITY3>-<LAST3>-<NNNN>'}, where CITY3 is the
225	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
226	     * last name, and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
227	     * owners already in that city at the time the owner was created.
228	     */
229	    private String nextCustomerCode(String city, String lastName) {
230	        String city3 = prefix3(city);
231	        String last3 = prefix3(lastName);
232	        String cityKey = normaliseIdentity(city);
233	        int sequence = (int) this.clinicService.findAllOwners().stream()
234	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
235	            .count() + 1;
236	        return String.format("%s-%s-%04d", city3, last3, sequence);
237	    }
238	
239	    /**
240	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
241	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
242	     */
243	    static LocalDate toBusinessDay(LocalDate date) {
244	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
245	            date = date.plusDays(1);
246	        }
247	        return date;
248	    }
249	
250	    /**
251	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
252	     * using the same per-day accumulation path as the daily create-limit rule.
253	     */
254	    private long ownersCreatedOn(LocalDate registrationDate) {
255	        LocalDate day = toBusinessDay(registrationDate);
256	        return this.clinicService.findAllOwners().stream()
257	            .map(Owner::getRegistrationDate)
258	            .filter(existing -> existing != null)
259	            .map(OwnerRestControllerV1::toBusinessDay)
260	            .filter(day::equals)
261	            .count();
262	    }
263	
264	    /**
265	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
266	     * postcode against the owner's city region.
267	     */
268	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
269	        "NSW", new int[] {2000, 2099},
270	        "VIC", new int[] {3000, 3099},
271	        "QLD", new int[] {4000, 4099});
272	
273	    /**
274	     * Resolve an owner's region from the city using the fixed city-to-region table
275	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
276	     * when the city is not listed.
277	     */
278	    private static String regionForCity(String city) {
279	        return switch (city == null ? "" : city) {
280	            case "Sydney" -> "NSW";
281	            case "Melbourne" -> "VIC";
282	            case "Brisbane" -> "QLD";
283	            default -> "UNKNOWN";
284	        };
285	    }
286	
287	    /**
288	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
289	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
290	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
291	     */
292	    private static boolean isPostcodeValid(String postcode, String city) {
293	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
294	            return false;
295	        }
296	        int[] range = REGION_POSTCODES.get(regionForCity(city));
297	        if (range == null) {
298	            return true;
299	        }
300	        int value = Integer.parseInt(postcode);
301	        return value >= range[0] && value <= range[1];
302	    }
303	
304	    /** Upper-cased first three characters of {@code value} (fewer if it is shorter); "" when null. */
305	    private static String prefix3(String value) {
306	        String letters = value == null ? "" : value;
307	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase();
308	    }
309	
310	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
311	    @Override
312	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
313	        Collection<Owner> owners;
314	        if (lastName != null) {
315	            owners = this.clinicService.findOwnerByLastName(lastName);
316	        } else {
317	            owners = this.clinicService.findAllOwners();
318	        }
319	        if (owners.isEmpty()) {
320	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
321	        }
322	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
323	    }
324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
328	        Owner owner = this.clinicService.findOwnerById(ownerId);
329	        if (owner == null) {
330	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
331	        }
332	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
333	        ownerDto.setBulkSignupWarning(owner.getRegistrationDate() != null
334	            && ownersCreatedOn(owner.getRegistrationDate()) > 80);
335	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
336	    }
337	
338	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
339	    @Override
340	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
341	        String telephone = toE164(ownerFieldsDto.getTelephone());
342	        if (telephone == null) {
343	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
344	        }
345	        String email = ownerFieldsDto.getEmail();
346	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
347	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
348	        }
349	        String address = normaliseAddress(ownerFieldsDto.getAddress());
350	        if (address.isEmpty()) {
351	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
352	        }
353	        String postcode = ownerFieldsDto.getPostcode();
354	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
355	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
356	        }
357	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
358	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
359	        LocalDate registrationDate = toBusinessDay(effectiveDate);
360	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
361	            .map(Owner::getRegistrationDate)
362	            .filter(existing -> existing != null)
363	            .map(OwnerRestControllerV1::toBusinessDay)
364	            .filter(registrationDate::equals)
365	            .count();
366	        if (ownersCreatedThatDay >= 100) {
367	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
368	        }
369	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
370	        long ownersInCity = this.clinicService.findAllOwners().stream()
371	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
372	            .count();
373	        if (ownersInCity >= 50) {
374	            return new ResponseEntity<>(HttpStatus.CONFLICT);
375	        }
376	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
377	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
378	        String addressKey = address;
379	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
380	            .filter(existing ->
381	                normaliseIdentity(existing.getLastName()).equals(lastNameKey)
382	                    && normaliseAddress(existing.getAddress()).equals(addressKey))
383	            .toList();
384	        String householdId = (sharesHousehold && !householdMembers.isEmpty())
385	            ? householdId(lastNameKey, addressKey) : null;
386	        String identityKey = identityKey(telephone, email, householdId);
387	        boolean identityInUse = this.clinicService.findAllOwners().stream()
388	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
389	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
390	        if (identityInUse) {
391	            return new ResponseEntity<>(HttpStatus.CONFLICT);
392	        }
393	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
394	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
395	            .filter(existing ->
396	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
397	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
398	            .count();
399	        HttpHeaders headers = new HttpHeaders();
400	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
401	        owner.setNamesakeCount(namesakeCount);
402	        owner.setAddress(address);
403	        owner.setTelephone(telephone);
404	        owner.setEmail(email == null ? null : email.toLowerCase());
405	        owner.setRegistrationDate(registrationDate);
406	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
407	        if (householdId != null) {
408	            owner.setHouseholdId(householdId);
409	            for (Owner member : householdMembers) {
410	                if (member.getHouseholdId() == null) {
411	                    member.setHouseholdId(householdId);
412	                    this.clinicService.saveOwner(member);
413	                }
414	            }
415	        }
416	        this.clinicService.saveOwner(owner);
417	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
418	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
419	            ownerMapper.formatMembershipLevel(owner));
420	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
421	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
422	        headers.setLocation(UriComponentsBuilder.newInstance()
423	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
424	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
425	    }
426	
427	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
428	    @Override
429	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
430	        String telephone = toE164(ownerFieldsDto.getTelephone());
431	        if (telephone == null) {
432	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
433	        }
434	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
