440	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
441	        }
442	        currentOwner.setAddress(ownerFieldsDto.getAddress());
443	        currentOwner.setCity(ownerFieldsDto.getCity());
444	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
445	        currentOwner.setLastName(ownerFieldsDto.getLastName());
446	        currentOwner.setTelephone(telephone);
447	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
448	        this.clinicService.saveOwner(currentOwner);
449	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
450	    }
451	
452	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
453	    @Transactional
454	    @Override
455	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
456	        Owner owner = this.clinicService.findOwnerById(ownerId);
457	        if (owner == null) {
